class Random final : public openswd3::battle::LegacyBattleBoundedRandomPort {
public:
    u32 calls{};
    u32 last_bound{};

    [[nodiscard]] u32 random_bounded(const u32 bound) override {
        ++calls;
        last_bound = bound;
        return 7U;
    }
};

class UpdatePort final
    : public openswd3::battle::LegacyBattleActorFrameUpdatePort {
public:
    openswd3::battle::LegacyBattleActorFrameUpdateReply reply{
        .returned = true,
        .eax = 0U,
        .ecx = 0xABCDU,
        .edx = 0x9876U,
    };
    openswd3::battle::LegacyBattleActorFrameUpdateReply frame_reply{
        .returned = true,
        .eax = 0x00701000U,
        .ecx = 0xBEEFU,
        .edx = 0x9876U,
        .flags = {.zero = true},
        .flags_known = true,
    };
    u32 calls{};
    u32 last_token{};
    u32 frame_calls{};
    u32 last_action_value{};
    u32 last_argument_zero{};

    [[nodiscard]] openswd3::battle::LegacyBattleActorFrameUpdateReply update(
        openswd3::asset_runtime::LegacyActionRecord& record,
        const u32 record_token,
        const u32 entry_eax,
        const u32 entry_ecx,
        const u32 entry_edx
    ) override {
        ++calls;
        last_token = record_token;
        static_cast<void>(entry_eax);
        static_cast<void>(entry_ecx);
        static_cast<void>(entry_edx);
        record.field_24 = 0x5AU;
        return reply;
    }

    [[nodiscard]] openswd3::battle::LegacyBattleActorFrameUpdateReply
    lookup_frame(
        const u32 action_value,
        const u32 argument_zero,
        const u32 entry_eax,
        const u32 entry_ecx,
        const u32 entry_edx
    ) override {
        ++frame_calls;
        last_action_value = action_value;
        last_argument_zero = argument_zero;
        static_cast<void>(entry_eax);
        static_cast<void>(entry_ecx);
        static_cast<void>(entry_edx);
        return frame_reply;
    }
};

